static ListNode reverseList(ListNode head) {
    ListNode prev = null;
    // 已反转部分的头（最终返回值）
    ListNode curr = head;
    while (curr != null) {
        ListNode nxt = curr.next;
        // 先保存后继，再改 curr.next
        curr.next = prev;
        prev = curr;
        curr = nxt;
    }
    return prev;
}

