class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        ListNode dummy = new ListNode(0, head);
        ListNode pre = dummy;
        ListNode current = head;
        while (current != null) {
            // 升序下相同值连在一起，与后继相同就要整段删掉
            if (current.next != null && current.val == current.next.val) {
                int duplicateValue = current.val;
                while (current != null && current.val == duplicateValue) {
                    current = current.next;
                }
                // pre 停在上一个保留结点，直接跨过这一整段
                pre.next = current;
            } else {
                // 与后继不同，这个值只出现一次，可以接到保留链上
                pre = current;
                current = current.next;
            }
        }
        return dummy.next;
    }
}

// LC138 输入是有限、next 无环的链表，random 仅指向本条链上的节点或 null，头节点可为 null。主穿插法还要求允许临时改写原 next，正常完成后恢复原链；有只读或共享并发读取约束时，改用以节点身份为键的映射法，需 O(n) 工作空间。
import java.util.*;
// Java 常用集合、队列、堆与数组工具
class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) return null;
        // 复制节点紧挨原节点，后面才能用 next 找到对应副本。
        Node current = head;
        while (current != null) {
            Node copy = new Node(current.val);
            copy.next = current.next;
            current.next = copy;
            current = copy.next;
        }
        // A.random.next 就是 A.random 的副本，赋给 A'。
        current = head;
        while (current != null) {
            if (current.random != null) {
                current.next.random = current.random.next;
            }
            current = current.next.next;
        }
        // 原链 next 跳回下一个原节点，复制链 next 跳到下一个副本。
        Node newHead = head.next;
        current = head;
        while (current != null) {
            Node copy = current.next;
            current.next = copy.next;
            copy.next = (copy.next == null) ? null : copy.next.next;
            current = current.next;
        }
        return newHead;
    }
}

public final class KthFromEnd {
    public static final class Node {
        public final int value;
        public Node next;
        public Node(int value){
            this.value=value;
        }
    }
    /** Trusted acyclic list: one forward traversal, no preliminary cycle scan. */
    public static Node findAcyclic(Node head, int k) {
        if (k <= 0) throw new IllegalArgumentException("positive k");
        Node fast = head, slow = head;
        for (int i = 0; i < k; i++) {
            if (fast == null) throw new IllegalArgumentException("k exceeds length");
            fast = fast.next;
        }
        while (fast != null) {
            fast = fast.next;
            slow = slow.next;
        }
        return slow;
    }
    /** Defensive wrapper; adds an O(n) cycle-validation traversal. */
    public static Node find(Node head, int k) {
        if (k <= 0) throw new IllegalArgumentException("positive k");
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) throw new IllegalArgumentException("acyclic list required");
        }
        return findAcyclic(head, k);
    }
}

/** Stable in-place partition: values < pivot, then values >= pivot. */
public final class StableListPartition {
    private StableListPartition() {
    }
    public static final class Node {
        public final int value;
        public Node next;
        public Node(int value) {
            this.value = value;
        }
    }
    /** Reject cyclic input before modifying any link. Caller owns the list. */
    public static Node partition(Node head, int pivot) {
        requireAcyclic(head);
        Node lowDummy = new Node(0), highDummy = new Node(0);
        Node lowTail = lowDummy, highTail = highDummy;
        for (Node current = head; current != null;) {
            Node next = current.next;
            // Save the unprocessed suffix first.
            current.next = null;
            // Detach; prevent stale links across buckets.
            if (current.value < pivot) {
                lowTail.next = current;
                lowTail = current;
            } else {
                highTail.next = current;
                highTail = current;
            }
            current = next;
        }
        lowTail.next = highDummy.next;
        return lowDummy.next;
    }
    private static void requireAcyclic(Node head) {
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) throw new IllegalArgumentException("cyclic list");
        }
    }
}
